public class Point{public float x_,z_;}public class Player{public Point pos_=new Point();}public class Manager{public int state_;}public class UserData{public Manager gm_=new Manager();}
public class Fixture{public UserData udat_=new UserData();public Point pos_=new Point();public int sink;void Use(){sink++;}public void Run(Player player,bool coatOut_ok){if(!(udat_.gm_.state_!=0&&coatOut_ok)){if(pos_.z_>=900f||pos_.z_<=-900f||pos_.x_<=-450f||pos_.x_>=450f){return;}if(player.pos_.z_>=900f||player.pos_.z_<=-900f||player.pos_.x_<=-450f||player.pos_.x_>=450f){return;}}Use();}}
